{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Replace negative-score weighting with a uniform unit-margin pairwise softplus loss. Each valid target has one existing sampled negative, so averaging valid pairs implements the requested per-target mean across all four datasets.",
      "edits": [
        {
          "find": "    valid_pos = pos_scores[mask]\n    valid_neg = neg_scores[mask]\n    weights = torch.softmax(valid_neg.detach(), dim=0)\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    valid_pos = pos_scores[mask]\n    valid_neg = neg_scores[mask]\n    pairwise_loss = torch.nn.functional.softplus(1.0 + valid_neg - valid_pos)\n    return pairwise_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Apply unit-margin pairwise softplus loss to all four category models, preserving masking, sampling, GRU architecture, inference, and training settings."
}
